    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(g):
    seen=set();res=[]
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c]!=0 and (r,c) not in seen:
                q=deque([(r,c)]);seen.add((r,c));cells=[]
                while q:
                    y,x=q.popleft();cells.append((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx]!=0 and (ny,nx) not in seen:
                                seen.add((ny,nx));q.append((ny,nx))
                res.append(cells)
    return res
def solve(gi):
    out=[row[:] for row in gi]
    for cc in comps(gi):
        rs=[q[0] for q in cc];cs=[q[1] for q in cc]
        rr,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
        if len(cc)!=(r1-rr+1)*(c1-c0+1): continue
        pts=[(r,x) for r,x in cc if gi[r][x]==9]
        if not pts: continue
        del_=False
        if len(pts)==1: del_=True
        else:
            p0,q0=pts[0],pts[1]
            dr,dc=q0[0]-p0[0],q0[1]-p0[1]
            g=_gcd(abs(dr),abs(dc)) or 1; dr//=g;dc//=g
            ok=True
            for p in pts:
                if dr==0:
                    if p[0]!=p0[0]: ok=False;break
                elif dc==0:
                    if p[1]!=p0[1]: ok=False;break
                else:
                    if (p[0]-p0[0])*dc!=(p[1]-p0[1])*dr: ok=False;break
            del_=ok
        if del_:
            for r_,x_ in cc: out[r_][x_]=0
    return out
for i in range(1,5):
    print(i, solve(G[f'Demo pair {i} input'])==G[f'Demo pair {i} output'])
print(json.dumps(solve(G['Test input'])))

